# D23 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d23_flow.py   (모델·인터넷 불필요)
#   [대체 경로] LLM은 키워드로 도구를 고르는 규칙 함수, 임베딩은 글자 2개 묶음(bigram) 가짜 벡터로 흉내 낸다.
#   도구 부르기 → 문서 검색(RAG) → 위험한 도구는 확인 질문 → 실행까지 한 번에 확인
import math

DIM = 1024
DOCS = ["스케일링은 건강보험이 적용되어 본인 부담금이 약 만 오천 원이에요.",
        "예약을 취소하려면 하루 전까지 전화나 앱으로 알려 주세요.",
        "주차는 건물 지하 1층에서 두 시간 무료예요."]
SLOTS = {"2026-12-01": ["10:00", "14:00"]}
BOOKINGS: list[dict] = []
DANGEROUS = {"book_slot"}


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def embed(text: str) -> list[float]:
    v = [0.0] * DIM
    t = text.replace(" ", "")
    for i in range(len(t) - 1):
        v[(ord(t[i]) * 31 + ord(t[i + 1])) % DIM] += 1.0
    n = math.sqrt(sum(x * x for x in v)) or 1.0
    return [x / n for x in v]


def search_docs(query: str) -> str:
    q = embed(query)
    return max(DOCS, key=lambda d: sum(a * b for a, b in zip(q, embed(d))))   # 가장 가까운 조각


def run_tool(name: str, args: dict) -> dict:
    if name == "check_slots":
        return {"slots": SLOTS.get(args["date"], [])}
    if name == "search_docs":
        return {"chunk": search_docs(args["query"])}
    if name == "book_slot":
        BOOKINGS.append(args)
        return {"booked": args}
    return {"error": name}


def plan(text: str) -> tuple[str, dict]:               # 모의 LLM: 말 → (도구, 인자)
    if "빈 시간" in text:
        return "check_slots", {"date": "2026-12-01"}
    if "예약해" in text:
        return "book_slot", {"date": "2026-12-01", "time": "14:00"}
    return "search_docs", {"query": text}


pending = None
log = []
for said in ["스케일링 비용이 얼마예요", "내일 빈 시간 알려 줘", "내일 2시에 예약해 줘", "네"]:
    if said == "네" and pending:
        out = run_tool(*pending)
        pending = None
    else:
        name, args = plan(said)
        if name in DANGEROUS:
            pending, out = (name, args), {"confirm": "14:00에 예약할까요?"}   # 위험한 도구는 바로 실행하지 않음
        else:
            out = run_tool(name, args)
    log.append(out)
    print(f"사용자: {said}\n  결과: {out}")
check("건강보험" in log[0]["chunk"] and log[1]["slots"] == ["10:00", "14:00"] and "confirm" in log[2] and len(BOOKINGS) == 1,
      "검색은 스케일링 조각, 예약은 확인 뒤에 1건만 만들어져야 해요.")

