// D23 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_flow.ts   (모델·인터넷 불필요)
//   [대체 경로] LLM은 키워드로 도구를 고르는 규칙 함수, 임베딩은 글자 2개 묶음(bigram) 가짜 벡터로 흉내 낸다.
//   도구 부르기 → 문서 검색(RAG) → 위험한 도구는 확인 질문 → 실행까지 한 번에 확인
type Args = Record<string, string>;
type Call = [string, Args];
const DIM = 1024;
const DOCS = [
  "스케일링은 건강보험이 적용되어 본인 부담금이 약 만 오천 원이에요.",
  "예약을 취소하려면 하루 전까지 전화나 앱으로 알려 주세요.",
  "주차는 건물 지하 1층에서 두 시간 무료예요.",
];
const SLOTS: Record<string, string[]> = { "2026-12-01": ["10:00", "14:00"] };
const BOOKINGS: Args[] = [];
const DANGEROUS = new Set(["book_slot"]);

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function embed(text: string): number[] {
  const v = new Array<number>(DIM).fill(0);
  const t = text.replaceAll(" ", "");
  for (let i = 0; i < t.length - 1; i++) v[(t.charCodeAt(i) * 31 + t.charCodeAt(i + 1)) % DIM] += 1;
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => x / n);
}

function searchDocs(query: string): string {
  const q = embed(query);
  const score = (d: string): number => embed(d).reduce((s, x, j) => s + x * q[j], 0);
  return DOCS.reduce((a, b) => (score(b) > score(a) ? b : a)); // 가장 가까운 조각
}

function runTool([name, args]: Call): Record<string, unknown> {
  if (name === "check_slots") return { slots: SLOTS[args.date] ?? [] };
  if (name === "search_docs") return { chunk: searchDocs(args.query) };
  if (name === "book_slot") {
    BOOKINGS.push(args);
    return { booked: args };
  }
  return { error: name };
}

function plan(text: string): Call { // 모의 LLM: 말 → (도구, 인자)
  if (text.includes("빈 시간")) return ["check_slots", { date: "2026-12-01" }];
  if (text.includes("예약해")) return ["book_slot", { date: "2026-12-01", time: "14:00" }];
  return ["search_docs", { query: text }];
}

let pending: Call | null = null;
const log: Record<string, any>[] = [];
for (const said of ["스케일링 비용이 얼마예요", "내일 빈 시간 알려 줘", "내일 2시에 예약해 줘", "네"]) {
  let out: Record<string, unknown>;
  if (said === "네" && pending) {
    out = runTool(pending);
    pending = null;
  } else {
    const call = plan(said);
    if (DANGEROUS.has(call[0])) {
      pending = call; // 위험한 도구는 바로 실행하지 않음
      out = { confirm: "14:00에 예약할까요?" };
    } else out = runTool(call);
  }
  log.push(out);
  console.log(`사용자: ${said}\n  결과:`, out);
}
check(log[0].chunk.includes("건강보험") && log[1].slots.join() === "10:00,14:00" && "confirm" in log[2] && BOOKINGS.length === 1, "검색은 스케일링 조각, 예약은 확인 뒤에 1건만 만들어져야 해요.");

loop.python:
# D23 · Part 1·3 · 도구 호출 루프 (LLM → 부탁 쪽지 → 실행 → 결과 → 답) — 단독 실행 완성 코드 (Python 3.11)
# pip install anthropic==2.11.0
# 실행: python d23_loop.py   (ANTHROPIC_API_KEY가 있으면 실제 Claude의 tool use, 없으면 규칙 기반 모의 LLM)
#   [대체 경로] 키가 없으면 키워드로 도구를 고르는 '모의 LLM'이 같은 모양의 응답(tool_use / text)을 낸다.
import json
import os

SLOTS = {"2026-12-01": ["10:00", "14:00", "15:00"]}
TOOLS = [{"name": "check_slots", "description": "예약 가능한 시간을 알려 준다. date는 YYYY-MM-DD.",
          "input_schema": {"type": "object", "properties": {"date": {"type": "string"}}, "required": ["date"]}}]
SYSTEM = "오늘은 2026-11-30이야. 한국어 음성 비서로 짧게 답하고, 예약 시간은 도구로 확인해."


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def run_tool(name: str, args: dict) -> dict:
    if name == "check_slots":
        return {"date": args["date"], "slots": SLOTS.get(args["date"], [])}
    return {"error": f"없는 도구: {name}"}


def mock_llm(messages: list) -> dict:
    last = messages[-1]["content"]
    if isinstance(last, str):                          # 사용자 말 → 도구가 필요하면 부탁 쪽지
        if "빈 시간" in last or "비어" in last:
            return {"type": "tool_use", "id": "tu_1", "name": "check_slots", "input": {"date": "2026-12-01"}}
        return {"type": "text", "text": "도와드릴 수 있는 건 예약 확인이에요."}
    result = json.loads(last[0]["content"])            # 도구 결과 → 답 만들기
    times = ", ".join(t[:2] + "시" for t in result["slots"])
    return {"type": "text", "text": f"내일은 {times}가 비어 있어요."}


def real_llm(messages: list) -> dict:
    import anthropic                                   # 실제 경로: 키가 있을 때만
    r = anthropic.Anthropic().messages.create(model="claude-haiku-5-5", system=SYSTEM, tools=TOOLS,
                                              messages=messages, max_tokens=300)
    for b in r.content:
        if b.type == "tool_use":
            return {"type": "tool_use", "id": b.id, "name": b.name, "input": b.input}
    return {"type": "text", "text": "".join(b.text for b in r.content if b.type == "text")}


def agent(question: str, llm, max_steps: int = 5) -> tuple[str, list]:
    messages, calls = [{"role": "user", "content": question}], []
    for _ in range(max_steps):                         # 무한 반복 방지 상한
        out = llm(messages)
        if out["type"] == "text":
            return out["text"], calls
        calls.append(out["name"])
        result = run_tool(out["name"], out["input"])   # 도구는 LLM이 아니라 우리 코드가 실행한다
        messages.append({"role": "assistant", "content": [dict(out)]})
        messages.append({"role": "user", "content": [{"type": "tool_result", "tool_use_id": out["id"], "content": json.dumps(result, ensure_ascii=False)}]})
    return "처리하지 못했어요.", calls


llm = real_llm if os.environ.get("ANTHROPIC_API_KEY") else mock_llm
answer, calls = agent("내일 빈 시간 알려 줘", llm)
print("부른 도구:", calls, "\n답:", answer)
check(calls == ["check_slots"] and len(answer) > 0 and (llm is real_llm or "14시" in answer),
      "도구를 한 번 부르고, 그 결과로 답해야 해요.")

loop.typescript:
// D23 · Part 1·3 · 도구 호출 루프 (LLM → 부탁 쪽지 → 실행 → 결과 → 답) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_loop.ts   (ANTHROPIC_API_KEY가 있으면 fetch로 실제 Claude tool use, 없으면 모의 LLM)
//   [대체 경로] 키가 없으면 키워드로 도구를 고르는 '모의 LLM'이 같은 모양의 응답(tool_use / text)을 낸다.
type Block = Record<string, any>;
type Msg = { role: string; content: string | Block[] };
type Out = { type: "text"; text: string } | { type: "tool_use"; id: string; name: string; input: Record<string, string> };
type Llm = (messages: Msg[]) => Promise<Out>;

const SLOTS: Record<string, string[]> = { "2026-12-01": ["10:00", "14:00", "15:00"] };
const TOOLS = [{ name: "check_slots", description: "예약 가능한 시간을 알려 준다. date는 YYYY-MM-DD.", input_schema: { type: "object", properties: { date: { type: "string" } }, required: ["date"] } }];
const SYSTEM = "오늘은 2026-11-30이야. 한국어 음성 비서로 짧게 답하고, 예약 시간은 도구로 확인해.";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function runTool(name: string, args: Record<string, string>): Record<string, unknown> {
  if (name === "check_slots") return { date: args.date, slots: SLOTS[args.date] ?? [] };
  return { error: `없는 도구: ${name}` };
}

const mockLlm: Llm = async (messages) => {
  const last = messages[messages.length - 1].content;
  if (typeof last === "string") { // 사용자 말 → 도구가 필요하면 부탁 쪽지
    if (last.includes("빈 시간") || last.includes("비어")) return { type: "tool_use", id: "tu_1", name: "check_slots", input: { date: "2026-12-01" } };
    return { type: "text", text: "도와드릴 수 있는 건 예약 확인이에요." };
  }
  const result = JSON.parse(last[0].content) as { slots: string[] }; // 도구 결과 → 답 만들기
  return { type: "text", text: `내일은 ${result.slots.map((t) => t.slice(0, 2) + "시").join(", ")}가 비어 있어요.` };
};

const realLlm = (key: string): Llm => async (messages) => {
  // 실제 경로: 키가 있을 때만
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model: "claude-haiku-5-5", system: SYSTEM, tools: TOOLS, messages, max_tokens: 300 }),
  });
  const j = (await res.json()) as { content: Block[] };
  const use = j.content.find((b) => b.type === "tool_use");
  if (use) return { type: "tool_use", id: use.id, name: use.name, input: use.input };
  return { type: "text", text: j.content.filter((b) => b.type === "text").map((b) => b.text).join("") };
};

async function agent(question: string, llm: Llm, maxSteps: number = 5): Promise<[string, string[]]> {
  const messages: Msg[] = [{ role: "user", content: question }];
  const calls: string[] = [];
  for (let step = 0; step < maxSteps; step++) { // 무한 반복 방지 상한
    const out = await llm(messages);
    if (out.type === "text") return [out.text, calls];
    calls.push(out.name);
    const result = runTool(out.name, out.input); // 도구는 LLM이 아니라 우리 코드가 실행한다
    messages.push({ role: "assistant", content: [{ ...out }] });
    messages.push({ role: "user", content: [{ type: "tool_result", tool_use_id: out.id, content: JSON.stringify(result) }] });
  }
  return ["처리하지 못했어요.", calls];
}

const key = process.env.ANTHROPIC_API_KEY;
const [answer, calls] = await agent("내일 빈 시간 알려 줘", key ? realLlm(key) : mockLlm);
console.log("부른 도구:", calls, "\n답:", answer);
check(calls.join() === "check_slots" && answer.length > 0 && (key !== undefined || answer.includes("14시")), "도구를 한 번 부르고, 그 결과로 답해야 해요.");

schema.python:
# D23 · Part 2 · 함수 → 도구 설명서(JSON Schema) 변환 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d23_schema.py   (인터넷 불필요)
import inspect
import json

JSON_TYPES = {str: "string", int: "integer", float: "number", bool: "boolean"}


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def check_slots(date: str, part_of_day: str = "any") -> list:
    """진료 예약이 비어 있는 시간을 알려 준다. date는 YYYY-MM-DD 형식."""
    return []


def book_slot(date: str, time: str, name: str, people: int = 1) -> dict:
    """예약을 한 건 만든다. 되돌리기 어려우니 반드시 사용자 확인 뒤에 부른다."""
    return {}


def to_schema(fn) -> dict:
    sig = inspect.signature(fn)
    props = {n: {"type": JSON_TYPES[p.annotation]} for n, p in sig.parameters.items()}
    required = [n for n, p in sig.parameters.items() if p.default is inspect.Parameter.empty]   # 기본값 없는 인자만 필수
    return {"name": fn.__name__, "description": inspect.getdoc(fn),
            "parameters": {"type": "object", "properties": props, "required": required}}


def for_claude(s: dict) -> dict:
    return {"name": s["name"], "description": s["description"], "input_schema": s["parameters"]}


def for_openai(s: dict) -> dict:
    return {"type": "function", **s}


def for_gemini(s: dict) -> dict:
    return {"function_declarations": [s]}


schemas = [to_schema(f) for f in (check_slots, book_slot)]
print(json.dumps(for_claude(schemas[1]), ensure_ascii=False, indent=1))
check(schemas[0]["parameters"]["required"] == ["date"] and schemas[1]["parameters"]["required"] == ["date", "time", "name"]
      and for_claude(schemas[0])["input_schema"]["properties"]["date"]["type"] == "string"
      and schemas[1]["parameters"]["properties"]["people"]["type"] == "integer" and "function_declarations" in for_gemini(schemas[0]),
      "기본값이 없는 인자만 required, 같은 설명서를 회사별 겉모양으로 감싸요.")

schema.typescript:
// D23 · Part 2 · 함수 → 도구 설명서(JSON Schema) 변환 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_schema.ts   (인터넷 불필요)
//   TypeScript는 실행 중에 함수의 인자 모양을 읽을 수 없어서, 인자 목록을 코드에 적고 거기서 설명서를 만든다.
type Param = { name: string; type: "string" | "integer" | "number" | "boolean"; required: boolean };
type Spec = { name: string; description: string; params: Param[] };

const SPECS: Spec[] = [
  {
    name: "check_slots",
    description: "진료 예약이 비어 있는 시간을 알려 준다. date는 YYYY-MM-DD 형식.",
    params: [{ name: "date", type: "string", required: true }, { name: "part_of_day", type: "string", required: false }],
  },
  {
    name: "book_slot",
    description: "예약을 한 건 만든다. 되돌리기 어려우니 반드시 사용자 확인 뒤에 부른다.",
    params: [
      { name: "date", type: "string", required: true }, { name: "time", type: "string", required: true },
      { name: "name", type: "string", required: true }, { name: "people", type: "integer", required: false },
    ],
  },
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Schema = { name: string; description: string; parameters: { type: "object"; properties: Record<string, { type: string }>; required: string[] } };

function toSchema(s: Spec): Schema {
  const properties: Record<string, { type: string }> = {};
  for (const p of s.params) properties[p.name] = { type: p.type };
  const required = s.params.filter((p) => p.required).map((p) => p.name); // 기본값 없는 인자만 필수
  return { name: s.name, description: s.description, parameters: { type: "object", properties, required } };
}

const forClaude = (s: Schema) => ({ name: s.name, description: s.description, input_schema: s.parameters });
const forOpenai = (s: Schema) => ({ type: "function", ...s });
const forGemini = (s: Schema) => ({ function_declarations: [s] });

const schemas = SPECS.map(toSchema);
console.log(JSON.stringify(forClaude(schemas[1]), null, 1));
check(
  schemas[0].parameters.required.join() === "date" && schemas[1].parameters.required.join() === "date,time,name" &&
    forClaude(schemas[0]).input_schema.properties.date.type === "string" &&
