const FACT = "예약 취소는 하루 전까지 알려 주세요";
const TEXT = "한빛치과 안내 문서입니다. 진료 시간과 비용, 주차 정보를 차례로 설명합니다. " + FACT + ". 감사합니다.";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function chunkText(text: string, size: number, overlap: number): string[] {
  const step = size - overlap; // 다음 조각은 overlap만큼 앞에서 겹쳐 시작
  const out: string[] = [];
  for (let i = 0; i < Math.max(text.length - overlap, 1); i += step) out.push(text.slice(i, i + size));
  return out;
}

const start = TEXT.indexOf(FACT);
const size = start + Math.floor(FACT.length / 2); // 중요한 문장 한가운데에서 잘리도록 크기를 고름
const plain = chunkText(TEXT, size, 0);
const over = chunkText(TEXT, size, FACT.length);
console.log(`겹침 없음: ${plain.length}조각, 사실 문장이 한 조각에 통째로 있나? ${plain.some((c) => c.includes(FACT))}`);
