check(!plain.some((c) => c.includes(FACT)) && over.some((c) => c.includes(FACT)) && over.length >= plain.length, "겹치게 자르면 조각이 겹쳐서 문장이 반으로 갈라지지 않아요.");

search.typescript:
// D23 · Part 4 · 벡터 검색 (임베딩 → 코사인 유사도 → 상위 k개) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_search.ts   (모델 다운로드·인터넷 불필요)
//   [대체 경로] 진짜 임베딩 모델 대신 '글자 2개 묶음(bigram) 빈도'를 1024차원으로 접은 가짜 임베딩을 쓴다.
//   원리(문장 → 숫자 벡터 → 코사인 유사도 → 가장 가까운 조각)는 같다.
const DIM = 1024;
const DOCS = [
  "진료 시간은 평일 오전 9시부터 오후 6시까지이고 점심시간은 낮 1시부터 2시까지예요.",
  "스케일링은 건강보험이 적용되어 본인 부담금이 약 만 오천 원이에요.",
  "임플란트는 상담 후 진행하며 비용은 개당 백만 원 정도예요.",
  "예약을 취소하려면 하루 전까지 전화나 앱으로 알려 주세요.",
  "주차는 건물 지하 1층에서 두 시간 무료예요.",
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function embed(text: string): number[] {
  const v = new Array<number>(DIM).fill(0);
  const t = text.replaceAll(" ", "");
  for (let i = 0; i < t.length - 1; i++) v[(t.charCodeAt(i) * 31 + t.charCodeAt(i + 1)) % DIM] += 1;
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => x / n); // 길이 1로 맞춰 두면 내적 = 코사인 유사도
}

function topK(query: string, k: number = 2): [number, number][] {
  const q = embed(query);
  const scored: [number, number][] = DOCS.map((d, i) => [i, embed(d).reduce((s, x, j) => s + x * q[j], 0)]);
  return scored.sort((a, b) => b[1] - a[1]).slice(0, k); // 점수 큰 순서로 상위 k개
}

for (const q of ["스케일링 비용이 얼마예요", "예약 취소는 언제까지 가능해요", "주차 무료인가요"]) {
  console.log(`Q: ${q}`);
  for (const [i, s] of topK(q)) console.log(`   ${s.toFixed(2)}  ${DOCS[i].slice(0, 30)}…`);
}
check(topK("스케일링 비용이 얼마예요")[0][0] === 1 && topK("예약 취소는 언제까지 가능해요")[0][0] === 3 && topK("주차 무료인가요")[0][0] === 4, "질문과 가장 비슷한 조각이 1등이어야 해요.");

hybrid.typescript:
// D23 · Part 4 · 의미 · 단어 · 혼합 검색 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_hybrid.ts   (모델 다운로드·인터넷 불필요)
//   [대체 경로] 의미 검색은 글자 2개 묶음(bigram) 가짜 임베딩, 단어 검색은 IDF 가중 단어 일치로 흉내 낸다.
const DIM = 1024;
const DOCS = [
  "진료 시간은 평일 오전 9시부터 오후 6시까지이고 점심시간은 낮 1시부터 2시까지예요.",
  "스케일링은 건강보험이 적용되어 본인 부담금이 약 만 오천 원이에요.",
  "임플란트는 상담 후 진행하며 비용은 개당 백만 원 정도예요.",
  "예약을 취소하려면 하루 전까지 전화나 앱으로 알려 주세요.",
  "주차는 건물 지하 1층에서 두 시간 무료예요.",
];
const QUERIES: [string, number][] = [
  ["스케일링 비용", 1], ["주차장 무료예요?", 4], ["치과 취소 방법", 3],
  ["임플란트 비용", 2], ["몇 시까지 진료해요", 0], ["점심시간 몇 시", 0],
]; // (질문, 정답 조각 번호)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function embed(text: string): number[] {
  const v = new Array<number>(DIM).fill(0);
  const t = text.replaceAll(" ", "");
  for (let i = 0; i < t.length - 1; i++) v[(t.charCodeAt(i) * 31 + t.charCodeAt(i + 1)) % DIM] += 1;
  const n = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
  return v.map((x) => x / n);
}

type Score = (q: string, i: number) => number;
const semantic: Score = (q, i) => { // 의미(글자 모양) 유사도
  const a = embed(q);
  return embed(DOCS[i]).reduce((s, x, j) => s + x * a[j], 0);
};
const idf = (w: string): number => Math.log((1 + DOCS.length) / (1 + DOCS.filter((d) => d.includes(w)).length)) + 1;
const keyword: Score = (q, i) => { // 질문 단어가 조각에 그대로 들어 있나 (드문 단어일수록 큰 점수)
  const words = q.split(" ").filter((w) => w.length >= 2);
  const total = words.reduce((s, w) => s + idf(w), 0) || 1;
  return words.filter((w) => DOCS[i].includes(w)).reduce((s, w) => s + idf(w), 0) / total;
};
const hybrid: Score = (q, i) => {
  const best = Math.max(...DOCS.map((_, j) => semantic(q, j))) || 1;
  return (0.5 * semantic(q, i)) / best + 0.5 * keyword(q, i); // 두 점수를 같은 크기로 맞춰 반반 섞음
};

function hit1(score: Score): number {
  let hits = 0;
  for (const [q, gold] of QUERIES) {
    const order = DOCS.map((_, i) => i).sort((a, b) => score(q, b) - score(q, a));
    if (order[0] === gold) hits++;
  }
  return hits;
}

const hits: Record<string, number> = { 의미: hit1(semantic), 단어: hit1(keyword), 혼합: hit1(hybrid) };
for (const [name, h] of Object.entries(hits)) console.log(`${name} 검색 hit@1: ${h}/${QUERIES.length}`);
check(hits.혼합 === QUERIES.length && hits.의미 < hits.혼합 && hits.단어 < hits.혼합, "혼합 검색은 둘의 약점을 서로 메워 전부 맞혀야 해요.");

