# D23 · Part 5 · 확인 질문 게이트 — 단독 실행 완성 코드 (Python 3.11)
# pip install (없음 · 표준 라이브러리만)
# 실행: python d23_confirm.py   (LLM 없이 '게이트 코드'만 확인 · 인터넷 불필요)
#   [대체 경로] LLM이 예약 도구를 부르려 한다고 가정하고(고정 입력), 코드가 확인을 강제하는지 본다.
BOOKINGS: list[dict] = []
DANGEROUS = {"book_slot", "cancel_booking"}            # 되돌리기 어려운 도구
YES = ("네", "응", "맞아", "그래", "예")


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def raw_run(name: str, args: dict) -> dict:
    if name == "book_slot":
        BOOKINGS.append(args)
        return {"ok": True, "booked": args}
    return {"error": "unknown"}


class Gate:
    def __init__(self):
        self.pending = None                            # 확인을 기다리는 도구 호출 (코드가 들고 있음)

    def call(self, name: str, args: dict) -> dict:
        if name in DANGEROUS:
            self.pending = (name, args)                # 바로 실행하지 않고 확인 질문으로 바꾼다
            return {"needs_confirm": True, "question": f"{args['date']} {args['time']}에 예약할까요?"}
        return raw_run(name, args)

    def user_said(self, text: str) -> dict | None:
        if self.pending and text.strip().startswith(YES):   # 확인은 '사용자의 다음 말'에서만 받는다
            name, args = self.pending
            self.pending = None
            return raw_run(name, args)
        self.pending = None                            # 다른 말이면 보류한 호출은 버린다
        return None


gate = Gate()
first = gate.call("book_slot", {"date": "2026-12-01", "time": "14:00", "name": "지민"})
print("1) LLM이 예약 도구를 부름 →", first, "· 지금 예약 건수:", len(BOOKINGS))
after_no = gate.user_said("아니 잠깐만")
print("2) 사용자: '아니 잠깐만' →", after_no, "· 예약 건수:", len(BOOKINGS))
gate.call("book_slot", {"date": "2026-12-01", "time": "14:00", "name": "지민"})
done = gate.user_said("네, 해 주세요")
print("3) 사용자: '네, 해 주세요' →", done, "· 예약 건수:", len(BOOKINGS))
check(first.get("needs_confirm") is True and after_no is None and done and done["ok"] and len(BOOKINGS) == 1,
      "확인 전에는 예약이 0건, '아니'는 취소, '네' 뒤에만 1건이 생겨야 해요.")

