// D23 · Part 5 · 확인 질문 게이트 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_confirm.ts   (LLM 없이 '게이트 코드'만 확인 · 인터넷 불필요)
//   [대체 경로] LLM이 예약 도구를 부르려 한다고 가정하고(고정 입력), 코드가 확인을 강제하는지 본다.
type Args = Record<string, string>;
type Call = { name: string; args: Args };
const BOOKINGS: Args[] = [];
const DANGEROUS = new Set(["book_slot", "cancel_booking"]); // 되돌리기 어려운 도구
const YES = ["네", "응", "맞아", "그래", "예"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function rawRun(c: Call): Record<string, unknown> {
  if (c.name === "book_slot") {
    BOOKINGS.push(c.args);
    return { ok: true, booked: c.args };
  }
  return { error: "unknown" };
}

class Gate {
  pending: Call | null = null; // 확인을 기다리는 도구 호출 (코드가 들고 있음)

  call(name: string, args: Args): Record<string, unknown> {
    if (DANGEROUS.has(name)) {
      this.pending = { name, args }; // 바로 실행하지 않고 확인 질문으로 바꾼다
      return { needs_confirm: true, question: `${args.date} ${args.time}에 예약할까요?` };
    }
    return rawRun({ name, args });
  }

  userSaid(text: string): Record<string, unknown> | null {
    const p = this.pending;
    this.pending = null; // 다른 말이면 보류한 호출은 버린다
    if (p && YES.some((y) => text.trim().startsWith(y))) return rawRun(p); // 확인은 '사용자의 다음 말'에서만 받는다
    return null;
  }
}

const gate = new Gate();
const first = gate.call("book_slot", { date: "2026-12-01", time: "14:00", name: "지민" });
console.log("1) LLM이 예약 도구를 부름 →", first, "· 지금 예약 건수:", BOOKINGS.length);
const afterNo = gate.userSaid("아니 잠깐만");
