gate.call("book_slot", { date: "2026-12-01", time: "14:00", name: "지민" });
const done = gate.userSaid("네, 해 주세요");
console.log("3) 사용자: '네, 해 주세요' →", done, "· 예약 건수:", BOOKINGS.length);
check(first.needs_confirm === true && afterNo === null && done?.ok === true && BOOKINGS.length === 1, "확인 전에는 예약이 0건, '아니'는 취소, '네' 뒤에만 1건이 생겨야 해요.");

latency.typescript:
// D23 · Part 6 · 도구와 첫 소리 (지연) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d23_latency.ts   (단계 시간은 코드 안의 모의 값 · 인터넷 불필요)
//   [대체 경로] 실제 STT·LLM·DB 호출 대신 단계별 걸리는 시간(초)을 적어 두고 타임라인을 계산한다.
const STAGES = { endpoint: 0.5, stt: 0.3, llm_decide: 0.4, tool: 0.8, llm_answer: 0.6, tts_first: 0.2 };
const FILLER_TTS = 0.2; // '확인해 볼게요' 같은 짧은 말을 소리로 만드는 시간
const TOOL_B = 0.7; // 서로 독립인 두 번째 도구(문서 검색)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function firstSound(filler: boolean, tools: number[], parallel: boolean): number {
  const toolTime = tools.length === 0 ? 0 : parallel ? Math.max(...tools) : tools.reduce((a, b) => a + b, 0);
  const base = STAGES.endpoint + STAGES.stt + STAGES.llm_decide;
  if (filler) return base + FILLER_TTS; // 도구를 기다리는 동안 짧은 말을 먼저 한다
  return base + toolTime + STAGES.llm_answer + STAGES.tts_first;
}

const noTool = STAGES.endpoint + STAGES.stt + STAGES.llm_answer + STAGES.tts_first;
const serial = firstSound(false, [STAGES.tool, TOOL_B], false);
const par = firstSound(false, [STAGES.tool, TOOL_B], true);
const filler = firstSound(true, [STAGES.tool, TOOL_B], true);
for (const [name, t] of [["도구 없이", noTool], ["도구 2개 순서대로", serial], ["도구 2개 동시에", par], ["동시에 + 먼저 한마디", filler]] as [string, number][]) {
  console.log(`${name.padEnd(18)} 첫 소리까지 ${t.toFixed(2)}초`);
}
check(serial > par && par > filler && Math.abs(serial - par - 0.7) < 1e-9 && filler < noTool + 0.5, "독립 도구는 동시에 부르고, 기다리는 동안 한마디를 먼저 하면 첫 소리가 크게 빨라져요.");

